const mongoose = require('mongoose');

// Definiera ett användarschema
const userSchema = new mongoose.Schema({
  username: {
    type: String,
    required: [true, 'Användarnamn krävs'],
    unique: true,
    trim: true,
    minlength: 3
  },
  email: {
    type: String,
    required: true,
    unique: true,
    lowercase: true,
    match: [/^\w+([\.-]?\w+)*@\w+([\.-]?\w+)*(\.\w{2,3})+$/, 'Vänligen ange en giltig e-postadress']
  },
  password: {
    type: String,
    required: true,
    minlength: 6,
    select: false // Inkludera inte lösenord i queries som standard
  },
  role: {
    type: String,
    enum: ['user', 'admin'],
    default: 'user'
  },
  createdAt: {
    type: Date,
    default: Date.now
  },
  updatedAt: {
    type: Date,
    default: Date.now
  }
});

// Skapa och exportera modellen
const User = mongoose.model('User', userSchema);
module.exports = User;

const User = require('./models/User'); // Importera din modell

// CREATE - Lägg till ny användare
const createUser = async (userData) => {
  try {
    const newUser = new User(userData);
    const savedUser = await newUser.save();
    return savedUser;
  } catch (error) {
    console.error('Fel vid skapande av användare:', error);
  }
};

// READ - Hämta användare via ID
const getUserById = async (userId) => {
  try {
    const user = await User.findById(userId);
    return user;
  } catch (error) {
    console.error('Fel vid hämtning av användare:', error);
  }
};

// READ - Hämta alla användare
const getAllUsers = async () => {
  try {
    const users = await User.find();
    return users;
  } catch (error) {
    console.error('Fel vid hämtning av användare:', error);
  }
};

// UPDATE - Uppdatera användare
const updateUser = async (userId, updateData) => {
  try {
    const updatedUser = await User.findByIdAndUpdate(
      userId,
      updateData,
      { new: true, runValidators: true }
    );
    return updatedUser;
  } catch (error) {
    console.error('Fel vid uppdatering av användare:', error);
  }
};

// DELETE - Ta bort användare
const deleteUser = async (userId) => {
  try {
    const deletedUser = await User.findByIdAndDelete(userId);
    return deletedUser;
  } catch (error) {
    console.error('Fel vid borttagning av användare:', error);
  }
};

